mapper.select:
SELECT /*selectMasterMdSrSrCmsStateList*/ A.SR_NO AS SR_NO, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.USER_ID) AS REQ_USER_NAME, TO_CHAR (A.REQ_DATE, 'YYYY/MM/DD HH24:MI') AS REQ_DATE, NVL (A.SR_SUBJECT, A.REQ_REMARK) AS SR_SUBJECT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR01' AND CODE = A.SYS_TYPE) AS SYS_TEXT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR02' AND CODE = A.REQ_TYPE) AS REQ_TEXT, (SELECT TEXT1 FROM ICOMCOD1 WHERE TYPE = 'SR05' AND CODE = A.REQ_SR_TYPE) AS REQ_SR_TEXT, DECODE (A.RECV_FLAG, 'GA', '요청', 'GS', '요청취소', 'DS', '상신', 'PS', '처리중', 'PA', '처리완료', 'PB', '보류처리', 'GG', '완료') AS RECV_TEXT, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.CD_USER_ID) AS CD_USER_NAME, TO_CHAR (A.DF_DATE, 'YYYY/MM/DD HH24:MI') AS DF_DATE, A.DF_REMARK AS DF_REMARK, (SELECT USER_NAME_LOC FROM ICOMLUSR WHERE USER_ID = A.DS_USER_ID) AS DS_USER_NAME, TO_CHAR (A.FF_DATE, 'YYYY/MM/DD HH24:MI') AS FF_DATE, A.USER_ID AS USER_ID, A.RECV_FLAG AS RECV_FLAG, A.CD_USER_ID AS CD_USER_ID, A.DS_USER_ID AS DS_USER_ID, (SELECT TEXT1 FROM ICOMCOD2 WHERE COMPANY_CODE = 'KRKORE0001' AND TYPE = 'C001' AND CODE = A.REQ_DEPT) REQ_DEPT_NAME, A.SYS_TYPE as SYS_TYPE, A.REQ_SR_TYPE AS REQ_SR_TYPE, A.REQ_TYPE AS REQ_TYPE
FROM KEPASRDT A
WHERE A.RECV_FLAG IN ('GA','DS','PS')
WHERE A.RECV_FLAG IN ('GA','GS','DS','PS','PA','PB','GG')
AND TO_CHAR(A.REQ_DATE,'YYYYMMDD') BETWEEN #{st_from_date} AND #{st_to_date}
AND A.SYS_TYPE = #{st_sys_type}
AND A.REQ_TYPE = #{st_req_type}
AND A.REQ_SR_TYPE = #{st_req_sr_type}
AND A.USER_ID = #{st_kep_user_id}
AND A.DS_USER_ID = #{st_ds_user_id}
AND A.CD_USER_ID = #{st_cd_user_id}
AND A.SR_NO LIKE UPPER('%'||#{st_sr_no_f}||'%')
AND (A.SR_SUBJECT LIKE '%'||#{st_remark}||'%' or A.REQ_REMARK LIKE '%'||#{st_remark}||'%')
AND DECODE(A.RECV_FLAG,'GA','요청', 'GS','요청취소', 'DS','상신', 'PS','처리중', 'PA','처리완료', 'PB','보류처리', 'GG','완료') = #{st_recv_flag}
ORDER BY NVL(TO_CHAR(A.DF_DATE,'YYYYMMDD'),'19990101') DESC
ORDER BY NVL(TO_CHAR(A.FF_DATE,'YYYYMMDD'),'19990101') DESC
ORDER BY A.REQ_DATE DESC
